<?php
require __DIR__ . '/auth.php'; requireLogin();
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT); if(!$id){http_response_code(400);exit('Invalid entry ID.');}
$stmt=$db->prepare('SELECT * FROM lunches WHERE id=? AND user_id=?'); $stmt->execute([$id,$_SESSION['user_id']]); $item=$stmt->fetch(); if(!$item){http_response_code(404);exit('Food entry not found.');}
$meals=['Breakfast'=>'08:00-09:00','Morning Snack'=>'10:30-11:00','Lunch'=>'12:00-13:00','Evening Snack'=>'16:30-17:00','During Duty'=>'20:00-21:00','Dinner'=>'22:15-22:45'];
function displayDate(string $iso):string{$t=strtotime($iso);return $t?date('d-m-Y',$t):$iso;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f172a"><title>Edit Food Entry</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#0f172a;font-family:Inter,system-ui,sans-serif}.wrap{width:min(100% - 24px,650px);margin:auto;padding:28px 0}.card{background:#fff;border:1px solid #e2e8f0;border-radius:22px;padding:24px;box-shadow:0 12px 32px #0f172a12}h1{margin:0 0 5px}.sub{color:#64748b;font-size:13px;margin-bottom:20px}label{display:block;font-size:12px;font-weight:800;margin:13px 0 7px}input,select,button{width:100%;font:inherit;border-radius:12px;padding:12px 13px}input,select{border:1px solid #d6dde8;background:#fff}button{border:0;background:#0f172a;color:#fff;font-weight:800;margin-top:16px}.back{display:inline-block;margin-bottom:15px;color:#1d4ed8;text-decoration:none;font-weight:800;font-size:13px}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:600px){.row{grid-template-columns:1fr}.card{padding:18px}}</style></head><body><main class="wrap"><a class="back" href="index.php">← Back to Dashboard</a><section class="card"><h1>✏️ Edit Food Entry</h1><div class="sub">Update your meal details. Dates use DD-MM-YYYY.</div><form method="post" action="update.php"><input type="hidden" name="csrf_token" value="<?=h(csrfToken())?>"><input type="hidden" name="id" value="<?=h((string)$item['id'])?>"><div class="row"><div><label>Date</label><input id="date_display" value="<?=h(displayDate($item['lunch_date']))?>" maxlength="10" inputmode="numeric" required><input type="hidden" name="lunch_date" id="lunch_date" value="<?=h($item['lunch_date'])?>"></div><div><label>Meal</label><select name="meal_type"><?php foreach($meals as $name=>$time):?><option value="<?=h($name)?>" <?=$item['meal_type']===$name?'selected':''?>><?=h($name)?></option><?php endforeach;?></select></div></div><label>Food Item</label><input name="food_item" maxlength="150" value="<?=h($item['food_item'])?>" required><div class="row"><div><label>Quantity</label><input name="quantity" maxlength="80" value="<?=h($item['quantity']??'')?>"></div><div><label>Notes</label><input name="notes" maxlength="250" value="<?=h($item['notes']??'')?>"></div></div><button>Save Changes</button></form></section></main><script>document.querySelector('form').addEventListener('submit',e=>{const m=document.getElementById('date_display').value.trim().match(/^(\d{2})-(\d{2})-(\d{4})$/);if(!m){e.preventDefault();alert('Use DD-MM-YYYY format.');return}const x=new Date(Date.UTC(+m[3],+m[2]-1,+m[1]));if(x.getUTCFullYear()!=+m[3]||x.getUTCMonth()!=+m[2]-1||x.getUTCDate()!=+m[1]){e.preventDefault();alert('Invalid date.');return}document.getElementById('lunch_date').value=m[3]+'-'+m[2]+'-'+m[1]});</script></body></html>
